import json
from pathlib import Path
x=json.loads(Path('answer.json').read_text())
assert set(x)=={'diagnosis','decision','predictions','uncertainty','next_measurement'}
assert x['decision'] in {'a','b','neither','indeterminate'}
assert all(isinstance(x[k],str) and x[k] for k in ('diagnosis','uncertainty','next_measurement'))
assert len(x['predictions'])==2
assert {p['candidate'] for p in x['predictions']}=={'a','b'}
for p in x['predictions']:
    assert set(p)=={'candidate','latency','execution_change','evidence'}
    assert p['latency'] in {'improve','regress','indeterminate'}
    assert isinstance(p['execution_change'],str) and p['execution_change']
    assert isinstance(p['evidence'],list) and p['evidence'] and all(isinstance(v,str) and v for v in p['evidence'])
print('schema-ok')
PY
git diff --check; git status --short; git diff -- answer.json; date -u +%Y-%m-%dT%H:%M:%SZ"

